`timescale 1ps/1fs
module tb_vpair; reg ck=0;always #416.5 ck=~ck; reg rn=0;integer cyc=0,ph=0,mode_=0,err=0,count=0;reg[4:0]xv[0:1],xs[0:1];reg[1379:0]xd[0:1];wire[275:0]vo[0:3];wire[1103:0]ro[0:3];wire[3:0]fault;reg[275:0]hist[0:3][0:249];integer own[0:3];integer peer[0:3];reg[1103:0]word_;
function automatic integer age(input integer source_);begin age=mode_?(source_%2==0?249:238):(source_%2==0?36:31);end endfunction
ot_s81sl_rstop u0(.clk(ck),.rst_n(rn),.sid(4'd0),.ri_w(1104'd0),.ri_e(1104'd0),.vi(hist[1][age(1)-1]),.nx_eo(173'd0),.nx_wo(173'd0),.ci_dir(3'd0),.ci_b(1104'd0),.xf_v(xv[0]),.xf_s(xs[0]),.xf(xd[0]),.vo(vo[0]),.ro_e(ro[0]),.fault(fault[0]));
ot_s81sl_rstop u1(.clk(ck),.rst_n(rn),.sid(4'd1),.ri_w(1104'd0),.ri_e(1104'd0),.vi(hist[0][age(0)-1]),.nx_eo(173'd0),.nx_wo(173'd0),.ci_dir(3'd0),.ci_b(1104'd0),.xf_v(xv[1]),.xf_s(xs[1]),.xf(xd[1]),.vo(vo[1]),.ro_e(ro[1]),.fault(fault[1]));
ot_s81sl_rstopt_xo u2(.clk(ck),.rst_n(rn),.sid(4'd0),.ri_w(1104'd0),.ri_e(1104'd0),.vi(hist[3][age(3)-1]),.nx_eo(173'd0),.nx_wo(173'd0),.ci_dir(3'd0),.ci_b(1104'd0),.xf_v(xv[0]),.xf_s(xs[0]),.xf(xd[0]),.vo(vo[2]),.ro_e(ro[2]),.fault(fault[2]));
ot_s81sl_rstopt_xo u3(.clk(ck),.rst_n(rn),.sid(4'd1),.ri_w(1104'd0),.ri_e(1104'd0),.vi(hist[2][age(2)-1]),.nx_eo(173'd0),.nx_wo(173'd0),.ci_dir(3'd0),.ci_b(1104'd0),.xf_v(xv[1]),.xf_s(xs[1]),.xf(xd[1]),.vo(vo[3]),.ro_e(ro[3]),.fault(fault[3]));
always @(negedge ck)begin ph=cyc%800;mode_=cyc/800;rn=ph>=32;for(integer t=0;t<2;t++)begin xv[t]=0;xs[t]=0;xd[t]=0;if(ph>=100+20*t&&ph<104+20*t)begin word_=0;word_[0]=1;word_[3:1]=2;word_[8:4]=1;word_[12:9]=4'(t);word_[20:13]=8'(5*t);for(integer j=0;j<64;j++)word_[21+16*j+:16]=16'(16'h3f00+5*t+j);xv[t][0]=1;xs[t][0]=ph==100+20*t;xd[t][275:0]=276'(word_>>(276*(ph-100-20*t)));end end end
always @(posedge ck)begin for(integer n=0;n<4;n++)begin for(integer j=249;j>0;j--)hist[n][j]<=hist[n][j-1];hist[n][0]<=vo[n];end end
always @(posedge ck)begin cyc++;#1;for(integer n=0;n<4;n++)begin if(!rn)begin own[n]=-1;peer[n]=-1;end else begin if(fault[n])err++;if(ro[n][0])begin if(ro[n][20:13]==8'(5*(n%2)))own[n]=cyc;else begin peer[n]=cyc;count++;if(cyc-own[n^1]!=age(n^1)+2)begin err++;$display("VPAIR_BAD mode%0d dst%0d own%0d peer%0d age%0d",mode_,n,own[n^1],cyc,age(n^1));end else $display("VPAIR_AGE mode%0d src%0d VOedges%0d after_own_line%0d",mode_,n^1,age(n^1),cyc-own[n^1]);end end end end if(cyc==1599)begin $display("VPAIR_RESULT count%0d errors%0d",count,err);if(count==8&&err==0)$display("VPAIR_PASS");else $fatal(1,"VPAIR_FAIL");$finish;end end
endmodule
